def permute(n, k):
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i

    avail = list(range(1, n + 1))   # unused numbers, sorted
    odd, even = (n + 1) // 2, n // 2  # remaining odd / even counts
    res = []

    for pos in range(n):
        chosen = False
        for idx, c in enumerate(avail):
            if res and c % 2 == res[-1] % 2:
                continue
            o = odd - (c % 2)
            e = even - (1 - c % 2)
            m = o + e
            nxt = 1 - c % 2          # parity required at the next position
            if m == 0:
                cnt = 1
            else:
                need_nxt, need_other = (m + 1) // 2, m // 2
                if nxt == 1:
                    ok = (o == need_nxt and e == need_other)
                else:
                    ok = (e == need_nxt and o == need_other)
                cnt = fact[o] * fact[e] if ok else 0
            if k > cnt:
                k -= cnt
            else:
                res.append(c)
                avail.pop(idx)
                odd, even = o, e
                chosen = True
                break
        if not chosen:
            return []
    return res
